options.incomingScript:
function mapToDittoProtocol(headers, textPayload, bytePayload, contentType) {
    const jsonBody = JSON.parse(textPayload);
    const unitId = jsonBody.unitId;
    const ts = jsonBody.timestamp || new Date().toISOString();

    const temp = jsonBody.temperature;
    const hum  = jsonBody.humidity;
    const comp = jsonBody.compressorStatus;
    const eng  = jsonBody.energyConsumption;

    const tempStatus   = temp >= 10 ? 'critical' : temp >= 8 ? 'warning' : 'normal';
    const humStatus    = (hum > 80 || hum < 50) ? 'warning' : 'normal';
    const engEff       = eng >= 4 ? 'critical' : eng >= 3 ? 'inefficient' : 'normal';

    return Ditto.buildDittoProtocolMsg(
        'org.eclipse.ditto',
        unitId,
        'things',
        'twin',
        'commands',
        'modify',
        '/features',
        {},
        {
            temperature:  { properties: { value: temp,  status: tempStatus,   lastUpdated: ts } },
            humidity:     { properties: { value: hum,   status: humStatus,     lastUpdated: ts } },
            compressor:   { properties: { status: comp,                        lastUpdated: ts } },
            energy:       { properties: { consumption: eng, efficiency: engEff, lastUpdated: ts } },
            connectivity: { properties: { connected: true, lastSeen: ts } }
        }
    );
}

options.outgoingScript:
function mapFromDittoProtocol(namespace, name, group, channel, criterion, action, path, dittoHeaders, value, status, extra) {
    return null;
}

function mapFromDittoProtocol(namespace, name, group, channel, criterion, action, path, dittoHeaders, value, status, extra) {
    if (!value) return null;
    return {
        textPayload: JSON.stringify({
            unitId: name,
            event: action,
            path: path,
            value: value,
            timestamp: new Date().toISOString()
        })
    };
}
